import backtrader as bt


class NvdaPreEarningsMomentumBreakout(bt.Strategy):
    params = dict(
        nearest_support_low=6455.0,
        nearest_support_high=6465.0,
        key_support=6430.75,
        resistance=6496.25,
        target=6508.75,
        stop_loss=6455.0,
        volume_sma_period=20,
        risk_pct=0.01,
    )

    def __init__(self):
        self.volume_sma = bt.indicators.SimpleMovingAverage(
            self.data.volume, period=self.p.volume_sma_period)
        self.order = None
        self.pulled_back = False
        self.recovering = False

    def notify_order(self, order):
        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
            self.order = None

    def notify_trade(self, trade):
        if trade.isclosed:
            self.pulled_back = False
            self.recovering = False

    def next(self):
        if self.order:
            return

        if not self.position:
            if not self.pulled_back:
                if self.data.low[0] <= self.p.key_support:
                    self.pulled_back = True
            elif not self.recovering:
                if self.data.close[0] > self.data.close[-1]:
                    self.recovering = True
            else:
                above_support_zone = self.data.close[0] >= self.p.nearest_support_low
                breakout = (self.data.close[-1] <= self.p.resistance
                            and self.data.close[0] > self.p.resistance)
                increased_volume = self.data.volume[0] > self.volume_sma[0]

                if above_support_zone and breakout and increased_volume:
                    entry_price = self.data.close[0]
                    stop_distance = entry_price - self.p.stop_loss
                    if stop_distance > 0:
                        risk_amount = self.broker.getvalue() * self.p.risk_pct
                        size = int(risk_amount / stop_distance)
                        if size > 0:
                            self.order = self.buy(size=size)
        else:
            if self.data.close[0] >= self.p.target:
                self.order = self.close()
            elif self.data.close[0] < self.p.stop_loss:
                self.order = self.close()
            elif (self.data.close[0] < self.data.open[0]
                  and self.data.close[0] < self.data.close[-1]
                  and self.data.volume[0] > self.volume_sma[0]):
                self.order = self.close()
